import type { AvatarPackage } from '@naavos/schema';

import { renderContext } from '../context.js';
import type { FileMap } from '../index.js';

export function cursorAdapter(pkg: AvatarPackage): FileMap {
  return new Map([
    [
      '.cursorrules',
      '# .cursorrules — NAAvOS Integration\n\n> Generated by NAAvOS. Recompile to update.\n\n' +
        renderContext(pkg),
    ],
  ]);
}
